      '<button type="button" data-subview="model"' + (state.subview === "model" ? ' class="on"' : "") + ">Funding model</button>" +
      '<button type="button" data-subview="report"' + (state.subview === "report" ? ' class="on"' : "") + ">📄 Report</button></div>";
